public interface ItemReader<T> {
  T read() throws Exception;      // next item, or null when the input is finished
}

FlatFileItemReader<CsvRow> csvReader() {
  return new FlatFileItemReaderBuilder<CsvRow>()
    .name("csvReader")             // the key its position is saved under
    .resource(new FileSystemResource("customers.csv"))
    .delimited().names("id", "name", "email")
    .linesToSkip(1)                // skip the header line
    .targetType(CsvRow.class)
    .build();
}

c-bi-processor:
ItemProcessor<CsvRow, Customer> cleanAndValidate() {
  return row -> {
    if (row.email().isBlank()) return null;            // filter: quietly drop it
    if (!row.email().contains("@"))
      throw new ValidationException(row.id());          // error: a real failure
    return new Customer(row.name().trim(),
                        row.email().toLowerCase());     // transform
  };
}

c-bi-writer:
public interface ItemWriter<T> {
  void write(Chunk<? extends T> chunk) throws Exception;   // the whole chunk, at once
}

JdbcBatchItemWriter<Customer> jdbcWriter(DataSource dataSource) {
  return new JdbcBatchItemWriterBuilder<Customer>()
    .dataSource(dataSource)
    .sql("insert into customers (name, email) values (:name, :email)")
    .beanMapped()                  // :name and :email come from getters
    .build();
}

